# split-source: order=74 original-lines=1361-1384 hash=eb30d29ea7a426fa


def sync_embedded_liquid_kernel_bundle(entrypoints=None, *, source_root: Path | None = None) -> None:
    """Rebuild explicit source entrypoints using UTF-8, without changing runtime state."""
    root = Path(source_root or Path(__file__).resolve().parent).resolve()
    stream = io.BytesIO()
    with zipfile.ZipFile(stream, "w", compression=zipfile.ZIP_DEFLATED) as archive:
        for name in ("__init__.py", "control.py", "models.py", "agentic.py", "context.py", "execution.py", "README.md"):
            entry = zipfile.ZipInfo(name, (2026, 1, 1, 0, 0, 0))
            entry.compress_type = zipfile.ZIP_DEFLATED
            archive.writestr(entry, (root / "liquid_kernel" / name).read_bytes())
    encoded = base64.b64encode(stream.getvalue()).decode("ascii")
    assignment = "_EMBEDDED_LIQUID_KERNEL_PACKAGE_B64 = (\n" + "".join(
        '    "' + encoded[index:index + 120] + '"\n' for index in range(0, len(encoded), 120)
    ) + ")"
    for name in entrypoints or ("Clouds_Coder.py",):
        path = root / name
        text, count = re.subn(
            r"_EMBEDDED_LIQUID_KERNEL_PACKAGE_B64 = \(\n.*?\n\)",
            lambda _: assignment, path.read_text(encoding="utf-8"), count=1, flags=re.S,
        )
        if count != 1:
            raise RuntimeError(f"embedded package marker missing: {name}")
        path.write_text(text, encoding="utf-8")

# split-source: order=75 original-lines=1385-1477 hash=fdc3cd2277b9c272


def _ensure_embedded_liquid_kernel_package(package_root: Path | None = None) -> dict:
    """Upgrade framework code only; signed/evolved artifacts and state are immutable here."""
    raw_root = Path(package_root or (Path(__file__).resolve().parent / "liquid_kernel"))
    if raw_root.is_symlink() or (raw_root.exists() and not raw_root.is_dir()):
        raise RuntimeError("Liquid Kernel package root must be a real directory; existing data was preserved")
    root = raw_root.resolve(strict=False)
    payload = base64.b64decode(_EMBEDDED_LIQUID_KERNEL_PACKAGE_B64.encode("ascii"), validate=True)
    with zipfile.ZipFile(io.BytesIO(payload)) as archive:
        names = ("__init__.py", "control.py", "models.py", "agentic.py", "context.py", "execution.py", "README.md")
        contents = {name: archive.read(name) for name in names}
    embedded_version = int(re.search(r"^EVOLUTION_MODEL_CAPABILITY_VERSION = (\d+)$", contents["control.py"].decode(), re.M).group(1))
    required = names[:-1]
    capability = 0
    if (root / "control.py").is_file() and not (root / "control.py").is_symlink():
        match = re.search(r"^EVOLUTION_MODEL_CAPABILITY_VERSION = (\d+)$", (root / "control.py").read_text(encoding="utf-8", errors="replace"), re.M)
        capability = int(match.group(1)) if match else 0
    ready = root.is_dir() and all((root / name).is_file() and not (root / name).is_symlink() for name in required)
    same = ready and all((root / name).read_bytes() == contents[name] for name in required)
    if ready and capability > embedded_version:
        control = (root / "control.py").read_text(encoding="utf-8", errors="replace")
        if not re.search(r"^KERNEL_CONTRACT_VERSION = 1$", control, re.M):
            raise RuntimeError("Newer Liquid Kernel framework uses an incompatible contract; no files or evolved state were overwritten")
        return {"root": str(root), "ready": True, "restored": False, "source": "local",
                "required_files": list(required), "model_capability_version": capability,
                "embedded_version": embedded_version, "diagnosis": "compatible_newer_framework_preserved", "state_preserved": True}
    if same and capability == embedded_version:
        return {"root": str(root), "ready": True, "restored": False, "source": "local",
                "required_files": list(required), "model_capability_version": capability,
                "embedded_version": embedded_version, "diagnosis": "current", "state_preserved": True}
    for name, content in contents.items():
        if name.endswith(".py"):
            ast.parse(content.decode("utf-8"), filename=name)
    root.mkdir(parents=True, exist_ok=True)
    lock_path = root / ".framework-upgrade.lock"
    for attempt in range(2):
        try:
            lock_fd = os.open(lock_path, os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o600)
            with os.fdopen(lock_fd, "w") as handle:
                json.dump({"pid": os.getpid(), "created_at": time.time()}, handle)
            break
        except FileExistsError as exc:
            alive = True
            try:
                owner = json.loads(lock_path.read_text())
                pid = int(owner.get("pid", 0))
                if pid > 0:
                    try:
                        os.kill(pid, 0)
                    except ProcessLookupError:
                        alive = False
                elif time.time() - lock_path.stat().st_mtime > 120:
                    alive = False
            except (OSError, ValueError, TypeError):
                alive = time.time() - lock_path.stat().st_mtime <= 120
            if attempt or alive:
                raise RuntimeError("Liquid Kernel framework upgrade is already locked; existing kernels were preserved") from exc
            lock_path.unlink(missing_ok=True)
    backup = root / ".package-backups" / uuid.uuid4().hex
    existed = [name for name in names if (root / name).exists() or (root / name).is_symlink()]
    installed = []
    staged = {}
    try:
        backup.mkdir(parents=True)
        for name, content in contents.items():
            target = root / name
            temporary = root / f".{name}.{uuid.uuid4().hex}.tmp"
            temporary.write_bytes(content)
            staged[name] = temporary
            if name in existed:
                shutil.copy2(target, backup / name, follow_symlinks=False)
        for name, temporary in staged.items():
            os.replace(temporary, root / name)
            installed.append(name)
    except Exception as exc:
        for name in installed:
            if name in existed:
                os.replace(backup / name, root / name)
            else:
                (root / name).unlink(missing_ok=True)
        raise RuntimeError(f"Liquid Kernel framework upgrade rolled back: {type(exc).__name__}; evolved state was preserved") from exc
    finally:
        for temporary in staged.values():
            temporary.unlink(missing_ok=True)
        lock_path.unlink(missing_ok=True)
    # Only five named framework files were touched. Runtime config, registry,
    # signing keys, artifacts, canary assignments and user sessions stay intact.
    return {"root": str(root), "ready": True, "restored": True, "source": "embedded",
            "required_files": list(required), "model_capability_version": embedded_version,
            "previous_version": capability, "embedded_version": embedded_version,
            "diagnosis": "upgraded" if capability < embedded_version else "repaired_framework",
            "state_preserved": True, "backup_root": str(backup)}

# split-source: order=78 original-lines=1486-1501 hash=861baa5a704fc2e7


def _ensure_liquid_kernel_sqlite_lifecycle(registry_class) -> None:
    """Close legacy local-package connections without replacing customized files."""
    if getattr(registry_class, "SQLITE_CONNECTIONS_CLOSE_ON_EXIT", False):
        return
    original_connect = registry_class._connect

    @contextlib.contextmanager
    def managed_connect(self):
        with contextlib.closing(original_connect(self)) as conn:
            with conn:
                yield conn

    registry_class._connect = managed_connect
    registry_class.SQLITE_CONNECTIONS_CLOSE_ON_EXIT = True

# split-source: order=968 original-lines=16358-16362 hash=5cd9aacc032a0f5b


def _liquid_kernel_history_present(runtime_root: Path) -> bool:
    root = Path(runtime_root)
    return root.is_dir() and any((root / name).exists() for name in ("registry.sqlite", "active.json", "artifacts"))

# split-source: order=969 original-lines=16363-16392 hash=af942e21e79e26a3


def prepare_liquid_kernel_runtime(runtime_root: Path, startup_policy: object = "inherit") -> dict:
    raw_root = Path(runtime_root)
    if raw_root.is_symlink() or (raw_root.exists() and not raw_root.is_dir()):
        quarantine = raw_root.with_name(f"{raw_root.name}.invalid-{uuid.uuid4().hex[:12]}")
        raw_root.rename(quarantine)
    root = raw_root.resolve(strict=False)
    root.parent.mkdir(parents=True, exist_ok=True)
    policy = normalize_liquid_kernel_startup_policy(startup_policy)
    history_present = _liquid_kernel_history_present(root)
    root.mkdir(parents=True, exist_ok=True)
    status = {
        "schema_version": 1,
        "runtime_root": str(root),
        "history_present": bool(history_present),
        "history_action": "inherited" if history_present else "initialized",
        "requested_policy": policy,
        "effective_policy": "inherit",
        "embedded_package": dict(LIQUID_KERNEL_PACKAGE_STATUS),
        "injected_version": "",
        "updated_at": now_ts(),
    }
    state_path = root.parent / LIQUID_KERNEL_BOOTSTRAP_STATE_FILENAME
    _write_json_file(state_path, status)
    try:
        os.chmod(state_path, 0o600)
    except Exception:
        pass
    return status

# split-source: order=970 original-lines=16393-16406 hash=bc332d47a0e9051a


def _persist_liquid_kernel_bootstrap(runtime_root: Path, status: dict) -> dict:
    root = Path(runtime_root).resolve(strict=False)
    state_path = root.parent / LIQUID_KERNEL_BOOTSTRAP_STATE_FILENAME
    payload = {str(key): value for key, value in dict(status or {}).items()}
    payload["runtime_root"] = str(root)
    payload["updated_at"] = now_ts()
    _write_json_file(state_path, payload)
    try:
        os.chmod(state_path, 0o600)
    except Exception:
        pass
    return payload
